class ProductRepository:
    def __init__(self):
        self._products = [
            {"id": 1, "name": "Steel Hammer", "category": "tools", "price": 25},
            {"id": 2, "name": "Rubber Mallet", "category": "tools", "price": 15},
            {"id": 3, "name": "Garden Hose", "category": "garden", "price": 40},
            {"id": 4, "name": "Steel Rake", "category": "garden", "price": 30},
        ]

    def list(self):
        return list(self._products)

    def search(self, q=None, category=None, max_price=None):
        results = []
        for p in self._products:
            if q is not None and q.lower() not in p["name"].lower():
                continue
            if category is not None and p["category"] != category:
                continue
            if max_price is not None and p["price"] > max_price:
                continue
            results.append(p)
        return results

